-- Read-only preflight; deliberately independent of Supabase migration history.
SELECT current_database() database_name,current_user database_user,now() checked_at;
SELECT e.object_name,to_regclass('public.'||e.object_name) IS NOT NULL installed FROM(VALUES('courses'),('course_sections'),('lessons'),('course_revisions'),('course_review_events'),('course_review_findings'),('quizzes'),('questions'),('question_options'),('assignment_definitions'),('assignment_submissions'))e(object_name) ORDER BY e.object_name;
SELECT column_name,data_type,udt_name,is_nullable,column_default FROM information_schema.columns WHERE table_schema='public' AND table_name='lessons' ORDER BY ordinal_position;
SELECT e.function_name,to_regprocedure(e.signature) IS NOT NULL installed FROM(VALUES('admin_set_lesson_video_metadata','public.admin_set_lesson_video_metadata(uuid,text,text,integer,text)'),('admin_reorder_course_sections','public.admin_reorder_course_sections(uuid,uuid[])'),('admin_reorder_section_lessons','public.admin_reorder_section_lessons(uuid,uuid,uuid[])'),('author_save_quiz','public.author_save_quiz(uuid,jsonb)'),('author_save_assignment','public.author_save_assignment(uuid,jsonb)'),('submit_course_for_review','public.submit_course_for_review(uuid,text)'),('admin_decide_course_review','public.admin_decide_course_review(uuid,text,text)'))e(function_name,signature) ORDER BY e.function_name;
SELECT 'duplicate_section_orders' anomaly,count(*) groups FROM(SELECT 1 FROM public.course_sections WHERE deleted_at IS NULL GROUP BY course_id,order_index HAVING count(*)>1)x
UNION ALL SELECT 'duplicate_lesson_orders',count(*) FROM(SELECT 1 FROM public.lessons WHERE deleted_at IS NULL AND section_id IS NOT NULL GROUP BY course_id,section_id,order_index HAVING count(*)>1)y
UNION ALL SELECT 'orphan_lessons',count(*) FROM public.lessons l LEFT JOIN public.course_sections s ON s.id=l.section_id AND s.deleted_at IS NULL WHERE l.deleted_at IS NULL AND(l.section_id IS NULL OR s.id IS NULL OR s.course_id<>l.course_id);
